+        ToolState::Running => Spinner::new().small().into_any_element(),
+        ToolState::Done => Icon::new(IconName::Check)
+            .small()
+            .text_color(theme.success)
+            .into_any_element(),
+        ToolState::Failed => Icon::new(IconName::X)
+            .small()
+            .text_color(theme.danger)
