+            .truncate()
+            .font_family(theme.mono_font_family.clone())
+            .text_color(theme.muted_foreground)
+            .child(highlighted_json(line, cx))
+            .into_any_element(),
+        None => muted("Waiting for the harness…".into()),
+    };
+    let detail = match row {
+        OutputRow::Text(text) if !text.trim().is_empty() => {
+            let line = text
+                .lines()
+                .rev()
+                .find(|line| !line.trim().is_empty())
+                .unwrap_or_default();
+            div()
+                .min_w_0()
+                .truncate()
+                .child(line.to_string())
+                .into_any_element()
+        }
+        OutputRow::Tool(call) => {
+            let project_dir = ProjectDirectory::get(cx);
+            let input = match &call.summary {
+                Some(summary) => div()
+                    .min_w_0()
+                    .truncate()
+                    .font_family(theme.mono_font_family.clone())
+                    .child(relative_to_project(summary, project_dir.as_deref()))
+                    .into_any_element(),
+                None => match ToolKind::of(&call.name).pending_input() {
+                    Some(label) => muted(label.into()),
+                    None => raw_line(),
+                },
+            };
+            h_flex()
+                .w_full()
+                .min_w_0()
+                .gap_2()
+                .when_some(call.shown_name(), |row, name| {
+                    row.child(div().flex_none().font_medium().child(name.to_string()))
+                })
+                .child(div().flex_1().min_w_0().child(input))
+                .into_any_element()
+        }
+        OutputRow::Error(error) => div()
+            .min_w_0()
+            .truncate()
+            .child(first_line(error))
+            .into_any_element(),
+        OutputRow::Text(_) | OutputRow::Pending => raw_line(),
+    };
+    let status = row_status(row, cx).or_else(|| {
+        (!reply.is_done()).then(|| Spinner::new().small().into_any_element())
+    });
+    let detail = div()
+        .id("ask-row-detail")
+        .w_full()
+        .min_w_0()
+        .child(detail);
+
+    Table::new()
+        // Legible at the window's base font size; tables are otherwise smaller.
+        .text_base()
+        .line_height(relative(1.5))
+        .rounded(theme.radius)
+        .border_1()
+        .border_color(theme.border)
+        .child(
+            TableBody::new().child(
+                TableRow::new()
+                    .child(
+                        TableCell::new()
+                            .w(KIND_WIDTH)
+                            .flex_none()
+                            .child(row.badge()),
+                    )
+                    .child(
+                        TableCell::new()
+                            .flex_1()
+                            .min_w_0()
+                            // Lets UI tests find the detail; inert in normal builds.
+                            .child(gpui_kit::TestSupportExt::test_support(detail)),
+                    )
+                    .child(
+                        TableCell::new()
+                            .w(STATUS_WIDTH)
+                            .flex_none()
+                            .children(status),
+                    ),
+            ),
+        )
+        .into_any_element()
+}
+
+/// What a running tool call shows while its input streams in: for a tool of a
+/// known kind, what it is getting ready to do, as tall as the raw output it
+/// replaces so the row keeps its height; for any other, the raw output.
+fn tool_input_pending(call: &ToolCall, reply: &Reply, cx: &App) -> AnyElement {
+    let Some(label) = ToolKind::of(&call.name).pending_input() else {
+        return raw_tail(reply, cx);
+    };
+    let theme = cx.theme();
+    v_flex()
+        .w_full()
+        .min_w_0()
+        .gap_1()
+        .child(div().text_color(theme.muted_foreground).child(label))
+        .child(Skeleton::new().w(relative(0.6)).h_4().rounded_md())
+        .into_any_element()
+}
