1	//! The hidden anchor. Prompts are typed as plain text, but behind the scenes
2	//! they are the `userPrompt` of a randomly-named Piton anchor whose imports
3	//! `piton lsp` adds automatically (see [`crate::piton_lsp`]), so they are never
4	//! written or seen. Each sent prompt is saved as a `.pi` file in the project's
5	//! prompt history and compiled; the compiled `userPrompt` is what the harness
6	//! receives.
7	
8	use std::collections::{BTreeMap, BTreeSet};
9	use std::fmt::Write as _;
10	use std::fs;
11	use std::hash::{BuildHasher, RandomState};
12	use std::path::{Path, PathBuf};
13	use std::process::Command;
14	use std::time::{SystemTime, UNIX_EPOCH};
15	
16	use anyhow::{Context as _, Result, anyhow};
17	use serde_json::Value;
18	
19	use crate::chat_input::SendMode;
20	use crate::project_directory::CONFIG_FILE_NAME;
21	
22	/// Indentation of each prompt line inside the anchor's `userPrompt` block.
23	pub const PROMPT_INDENT: &str = "        ";
24	
25	/// Where the application keeps its files, relative to the project directory.
26	pub const APP_DIR: &str = ".suspense";
27	const HISTORY_DIR: &str = "history";
28	/// Where questions asked from the Ask tab are saved, apart from the history.
29	const ASKS_DIR: &str = "asks";
30	
31	/// The hidden anchor's imports: names by module.
32	#[derive(Clone, Debug, Default)]
33	pub struct Imports(BTreeMap<String, BTreeSet<String>>);
34	
35	impl Imports {
36	    /// Adds the names of every `from <module> import A, B` line in `source`,
37	    /// ignoring other lines. Returns whether any name was new.
38	    pub fn add_from_source(&mut self, source: &str) -> bool {
39	        let mut added = false;
40	        for line in source.lines() {
41	            let Some((module, names)) = line
42	                .trim()
43	                .strip_prefix("from ")
44	                .and_then(|rest| rest.split_once(" import "))
45	            else {
46	                continue;
47	            };
48	            let names: Vec<&str> = names
49	                .split(',')
50	                .map(str::trim)
51	                .filter(|name| !name.is_empty())
52	                .collect();
53	            if names.is_empty() {
54	                continue;
55	            }
56	            let imported = self.0.entry(absolute_module(module.trim())).or_default();
57	            for name in names {
58	                added |= imported.insert(name.to_string());
59	            }
60	        }
61	        added
62	    }
63	
64	    /// Adds every name in `other`.
65	    pub fn extend(&mut self, other: &Imports) {
66	        for (module, names) in &other.0 {
67	            self.0
68	                .entry(module.clone())
69	                .or_default()
70	                .extend(names.iter().cloned());
71	        }
72	    }
73	}
74	
75	/// Relative imports come from a draft sitting at the spec root; the absolute
76	/// form resolves the same from anywhere in the project, history files included.
77	fn absolute_module(module: &str) -> String {
78	    match module.strip_prefix("./") {
79	        Some(path) => format!("/{path}"),
80	        None => module.to_string(),
81	    }
82	}
83	
84	pub struct HiddenAnchor {
85	    name: String,
86	    pub imports: Imports,
87	    /// The `systemPrompt` written after the `userPrompt`, if any.
88	    pub system_prompt: Option<String>,
89	}
90	
91	/// A compiled hidden anchor.
92	pub struct CompiledPrompt {
93	    pub user_prompt: String,
94	    pub system_prompt: Option<String>,
95	}
96	
97	impl HiddenAnchor {
98	    /// A freshly named anchor with no imports and no system prompt.
99	    pub fn random() -> Self {
100	        Self {
101	            name: format!(
102	                "Prompt_{:016x}",
103	                RandomState::new().hash_one(SystemTime::now())
104	            ),
105	            imports: Imports::default(),
106	            system_prompt: None,
107	        }
108	    }
109	
110	    pub fn name(&self) -> &str {
111	        &self.name
112	    }
113	
114	    /// The Piton source of this anchor with `prompt` as its `userPrompt`.
115	    pub fn source(&self, prompt: &str) -> String {
116	        let mut source = String::new();
117	        for (module, names) in &self.imports.0 {
118	            let names: Vec<&str> = names.iter().map(String::as_str).collect();
119	            writeln!(source, "from {module} import {}", names.join(", ")).ok();
120	        }
121	        writeln!(source, "\nanchor {}:\n    userPrompt:", self.name).ok();
122	        push_block(&mut source, prompt);
123	        // After the prompt, so the prompt's lines stay where
124	        // `prompt_first_line` says they are.
125	        if let Some(system_prompt) = &self.system_prompt {
126	            source.push('\n');
127	            source.push_str(SYSTEM_PROMPT_LINE);
128	            source.push('\n');
129	            push_block(&mut source, system_prompt);
130	        }
131	        source
132	    }
133	
134	    /// Reads back an anchor saved with [`Self::source`], with the prompt it
135	    /// holds.
136	    pub fn parse(source: &str) -> Option<(Self, String)> {
137	        let mut imports = Imports::default();
138	        let mut lines = source.lines();
139	        let name = loop {
140	            let line = lines.next()?;
141	            if let Some(name) = line
142	                .strip_prefix("anchor ")
143	                .and_then(|rest| rest.strip_suffix(':'))
144	            {
145	                break name.to_string();
146	            }
147	            imports.add_from_source(line);
148	        };
149	        if lines.next()?.trim() != "userPrompt:" {
150	            return None;
151	        }
152	        let lines: Vec<&str> = lines.collect();
153	        // Prompt lines are indented deeper, so only the property itself
154	        // matches this line.
155	        let (prompt, system_prompt) =
156	            match lines.iter().position(|line| *line == SYSTEM_PROMPT_LINE) {
157	                Some(at) => {
158	                    // Drop the blank line separating the two properties; prompt
159	                    // lines, even empty ones, are always indented.
160	                    let prompt = &lines[..at];
161	                    let prompt = prompt.strip_suffix(&[""]).unwrap_or(prompt);
162	                    (unindent(prompt), Some(unindent(&lines[at + 1..])))
163	                }
164	                None => (unindent(&lines), None),
165	            };
166	        Some((
167	            Self {
168	                name,
169	                imports,
170	                system_prompt,
171	            },
172	            prompt,
173	        ))
174	    }
175	
176	    /// The zero-based line of [`Self::source`] holding the prompt's first line.
177	    pub fn prompt_first_line(&self) -> u32 {
178	        self.imports.0.len() as u32 + 3
179	    }
180	}
181	
182	/// The line opening the `systemPrompt` property of [`HiddenAnchor::source`].
183	const SYSTEM_PROMPT_LINE: &str = "    systemPrompt:";
184	
185	/// The text of a property's indented lines, as written by [`push_block`].
186	fn unindent(block: &[&str]) -> String {
187	    block
188	        .iter()
189	        .map(|line| line.strip_prefix(PROMPT_INDENT).unwrap_or(line.trim()))
190	        .collect::<Vec<_>>()
191	        .join("\n")
192	}
193	
194	/// Adds `text` to `source` as the indented lines of a property.
195	fn push_block(source: &mut String, text: &str) {
196	    for line in text.split('\n') {
197	        source.push_str(PROMPT_INDENT);
198	        source.push_str(line.trim_end_matches('\r'));
199	        source.push('\n');
200	    }
201	}
202	
203	/// The system prompt a prompt sent in `mode` is given, naming the code and
204	/// spec locations set in the project's `piton.config.pi`.
205	pub fn system_prompt(mode: SendMode, project_dir: &Path) -> Result<String> {
206	    let code = config_value(project_dir, "codeRoot")?;
207	    let spec = config_value(project_dir, "root")?;
208	    Ok(match mode {
209	        SendMode::Code => format!(
210	            "We're working on the code located in {code}. Don't edit the spec located in {spec}."
211	        ),
212	        SendMode::Both => format!(
213	            "We're working on both the code located in {code} and the spec located in {spec}. Edit both of them."
214	        ),
215	        SendMode::Spec => format!(
216	            "We're working on the spec located in {spec}. Don't edit the code located in {code}."
217	        ),
218	        SendMode::Ask => format!(
219	            "We're only asking a question about the code located in {code} and the spec located in {spec}. Don't edit either of them."
220	        ),
221	    })
222	}
223	
224	/// The path the chat input's unsent text is presented to `piton lsp` under.
225	/// Nothing is written there. It sits inside the spec root because `piton lsp`
226	/// only resolves imports, and offers auto-imports, for documents under it.
227	pub fn draft_path(project_dir: &Path) -> PathBuf {
228	    let spec_root = spec_root(project_dir).unwrap_or_default();
229	    project_dir.join(spec_root).join(".suspense-draft.pi")
230	}
231	
232	/// The project's prompt history directory.
233	pub fn history_dir(project_dir: &Path) -> PathBuf {
234	    project_dir.join(APP_DIR).join(HISTORY_DIR)
235	}
236	
237	/// Saves `prompt`, as `anchor`'s source, to the project's prompt history.
238	pub fn save(anchor: &HiddenAnchor, prompt: &str, project_dir: &Path) -> Result<PathBuf> {
239	    save_in(&history_dir(project_dir), anchor, prompt)
240	}
241	
242	/// Saves a question, as `anchor`'s source, where it can be compiled without
243	/// joining the prompt history.
244	pub fn save_ask(anchor: &HiddenAnchor, prompt: &str, project_dir: &Path) -> Result<PathBuf> {
245	    save_in(&project_dir.join(APP_DIR).join(ASKS_DIR), anchor, prompt)
246	}
247	
248	fn save_in(dir: &Path, anchor: &HiddenAnchor, prompt: &str) -> Result<PathBuf> {
249	    fs::create_dir_all(dir).with_context(|| format!("could not create {}", dir.display()))?;
250	    let sent_at = SystemTime::now()
251	        .duration_since(UNIX_EPOCH)
252	        .map_or(0, |elapsed| elapsed.as_secs());
253	    let file = dir.join(format!("{sent_at}-{}.pi", anchor.name));
254	    fs::write(&file, anchor.source(prompt))
255	        .with_context(|| format!("could not save {}", file.display()))?;
256	    Ok(file)
257	}
258	
259	/// Compiles `file`, a saved `anchor`, and returns its compiled prompt text.
260	pub fn compile(anchor: &HiddenAnchor, file: &Path, project_dir: &Path) -> Result<CompiledPrompt> {
261	    let output = Command::new("piton")
262	        .args(["compile", "--stdout"])
263	        .arg(file)
264	        .current_dir(project_dir)
265	        .output()
266	        .context("could not run `piton compile`")?;
267	    if !output.status.success() {
268	        let mut message = String::from_utf8_lossy(&output.stdout).into_owned();
269	        message.push_str(&String::from_utf8_lossy(&output.stderr));
270	        return Err(anyhow!("{}", message.trim()));
271	    }
272	
273	    let compiled: Value =
274	        serde_json::from_slice(&output.stdout).context("`piton compile` did not print JSON")?;
275	    let compiled = compiled
276	        .get(&anchor.name)
277	        .ok_or_else(|| anyhow!("the compiled output has no {}", anchor.name))?;
278	    let user_prompt = compiled
279	        .get("userPrompt")
280	        .ok_or_else(|| anyhow!("the compiled anchor has no userPrompt"))?;
281	    Ok(CompiledPrompt {
282	        user_prompt: prose(user_prompt),
283	        system_prompt: compiled.get("systemPrompt").map(prose),
284	    })
285	}
286	
287	/// Reads the spec root (`root:`) from the project's `piton.config.pi`.
288	fn spec_root(project_dir: &Path) -> Result<PathBuf> {
289	    config_value(project_dir, "root").map(PathBuf::from)
290	}
291	
292	/// Reads the first `key:` value in the project's `piton.config.pi`.
293	pub fn config_value(project_dir: &Path, key: &str) -> Result<String> {
294	    let config_path = project_dir.join(CONFIG_FILE_NAME);
295	    let config = fs::read_to_string(&config_path)
296	        .with_context(|| format!("could not read {}", config_path.display()))?;
297	    config
298	        .lines()
299	        .find_map(|line| line.trim().strip_prefix(key)?.strip_prefix(':'))
300	        .map(|value| value.trim().to_string())
301	        .ok_or_else(|| anyhow!("{} has no {key}", config_path.display()))
302	}
303	
304	/// Turns a compiled `userPrompt` back into text: paragraphs are separated by
305	/// blank lines and lists become `- ` items.
306	fn prose(value: &Value) -> String {
307	    match value {
308	        Value::String(text) => text.clone(),
309	        Value::Array(blocks) => blocks
310	            .iter()
311	            .map(|block| match block {
312	                Value::Array(items) => items
313	                    .iter()
314	                    .map(|item| format!("- {}", prose(item)))
315	                    .collect::<Vec<_>>()
316	                    .join("\n"),
317	                other => prose(other),
318	            })
319	            .collect::<Vec<_>>()
320	            .join("\n\n"),
321	        Value::Null => String::new(),
322	        other => serde_json::to_string_pretty(other).unwrap_or_default(),
323	    }
324	}
