41	/// The tabs the input sits in, in the order Tab cycles them.
42	const TABS: [SendMode; 4] = [SendMode::Code, SendMode::Both, SendMode::Spec, SendMode::Ask];
43	
44	/// The side of the square chain tab, half the height of the tabs.
45	const BOTH_TAB_SIZE: Pixels = px(16.);
46	
47	/// Index of the chain tab in `TABS`.
48	const BOTH_TAB: usize = 1;
49	
50	/// Index of the Ask tab in `TABS`.
51	const ASK_TAB: usize = 3;
52	
53	/// The gap between Code and Spec while the chain is inactive: the chain, with
54	/// room either side so it overlaps neither tab.
55	const CHAIN_GAP: Pixels = px(16. + 6. * 2.);
56	
57	/// How the tabs slide toward and away from the chain: critically damped, so
58	/// they meet without bouncing past the seam.
59	const CHAIN_SPRING: SpringConfig = SpringConfig::new(400., 40., 1.);
60	
61	/// How strongly the selected tabs and their body are tinted: red for Code,
62	/// blue for Spec, purple for both, and green for Ask.
63	const TINT_OPACITY: f32 = 0.1;
64	
65	/// The tint at `position` between the tabs: red at Code (0), blue at Spec
66	/// (2), purple for both (1), where they meet, and green at Ask (3).
67	fn tint(red: Hsla, blue: Hsla, green: Hsla, position: f32) -> Hsla {
68	    if position > 2. {
69	        blend(blue, green, position - 2.)
70	    } else {
71	        blend(red, blue, position / 2.)
72	    }
73	}
74	
75	/// `from` blended `t` of the way to `to`, at the tint's opacity.
76	fn blend(from: Hsla, to: Hsla, t: f32) -> Hsla {
77	    let t = t.clamp(0., 1.);
78	    // The shorter way round the hue circle, which from red to blue passes
79	    // through purple rather than green.
80	    let hue_step = (to.h - from.h + 0.5).rem_euclid(1.) - 0.5;
81	    Hsla {
82	        h: (from.h + hue_step * t).rem_euclid(1.),
83	        s: from.s + (to.s - from.s) * t,
84	        l: from.l + (to.l - from.l) * t,
85	        a: TINT_OPACITY,
86	    }
87	}
88	
89	/// How much of tab `ix`'s tint shows with the tint at `position`: all of it
